/* Maintainer-only bundler: node scripts/build-local-ocr.js (Node 18+).
 * Users need neither Node nor a server. Keep the generated vendor folder with index.html.
 */
const fs = require('node:fs/promises');
const path = require('node:path');
const crypto = require('node:crypto');

const sources = {
  api: 'https://cdn.jsdelivr.net/npm/tesseract.js@6.0.1/dist/tesseract.min.js',
  worker: 'https://cdn.jsdelivr.net/npm/tesseract.js@6.0.1/dist/worker.min.js',
  core: 'https://cdn.jsdelivr.net/npm/tesseract.js-core@6.0.0/tesseract-core-lstm.wasm.js',
  fin: 'https://cdn.jsdelivr.net/npm/@tesseract.js-data/fin@1.0.0/4.0.0_best_int/fin.traineddata.gz',
  eng: 'https://cdn.jsdelivr.net/npm/@tesseract.js-data/eng@1.0.0/4.0.0_best_int/eng.traineddata.gz',
  'tesseract-LICENSE.txt': 'https://cdn.jsdelivr.net/npm/tesseract.js@6.0.1/LICENSE.md',
  'tesseract.min.js.LICENSE.txt': 'https://cdn.jsdelivr.net/npm/tesseract.js@6.0.1/dist/tesseract.min.js.LICENSE.txt',
  'worker.min.js.LICENSE.txt': 'https://cdn.jsdelivr.net/npm/tesseract.js@6.0.1/dist/worker.min.js.LICENSE.txt',
  'core-LICENSE.txt': 'https://cdn.jsdelivr.net/npm/tesseract.js-core@6.0.0/LICENSE',
  'tessdata-LICENSE.txt': 'https://raw.githubusercontent.com/naptha/tessdata/806cd9adc8c6e8abc11c782db1818c990576bebc/LICENSE'
};
const output = path.join(__dirname, '..', 'js', 'vendor', 'ocr');
const stripMap = source => source.replace(/^\/\/# sourceMappingURL=.*$/gm, '');

async function main() {
  const assets = Object.fromEntries(await Promise.all(Object.entries(sources).map(async ([name, url]) => {
    const response = await fetch(url);
    if (!response.ok) throw new Error(`${response.status}: ${url}`);
    return [name, Buffer.from(await response.arrayBuffer())];
  })));
  // The .wasm.js core contains its own WASM bytes. Use the portable LSTM build,
  // avoiding both file:// fetch restrictions and a mandatory SIMD dependency.
  if (!assets.core.includes(Buffer.from('data:application/octet-stream;base64,'))) {
    throw new Error('Expected an embedded-WASM core; refusing to build a network-dependent bundle.');
  }
  const languageData = { fin: assets.fin.toString('base64'), eng: assets.eng.toString('base64') };
  // Only language-file reads are handled here. No request ever falls through to the network.
  // A reserved .invalid URL is an internal lookup key for upstream's language loader.
  const workerSource = `
const bundledLanguages = ${JSON.stringify(languageData)};
self.fetch = async function (url) {
  const match = /^https:\\/\\/tiliweb-ocr\\.invalid\\/(fin|eng)\\.traineddata\\.gz$/.exec(String(url));
  if (!match) throw new Error('Offline OCR blocked an unexpected resource: ' + url);
  const bytes = Uint8Array.from(atob(bundledLanguages[match[1]]), c => c.charCodeAt(0));
  return new Response(bytes, { status: 200 });
};
${stripMap(assets.core.toString())}
${stripMap(assets.worker.toString())}
`;
  const bundle = `/* Generated by scripts/build-local-ocr.js. See accompanying licenses and manifest.json. */
${stripMap(assets.api.toString())}
;(function () {
  const workerUrl = URL.createObjectURL(new Blob([${JSON.stringify(workerSource)}], { type: 'text/javascript' }));
  const engine = window.Tesseract;
  window.TiliWebLocalOcr = {
    createWorker: (langs, oem, options) => engine.createWorker(langs, oem, {
      ...options, workerPath: workerUrl, workerBlobURL: false,
      corePath: 'bundled-core.js', langPath: 'https://tiliweb-ocr.invalid', cacheMethod: 'none'
    })
  };
  window.addEventListener('pagehide', event => { if (!event.persisted) URL.revokeObjectURL(workerUrl); });
})();
`;
  const manifest = Object.fromEntries(Object.entries(assets).map(([name, data]) => [name, {
    url: sources[name], bytes: data.length, sha256: crypto.createHash('sha256').update(data).digest('hex')
  }]));
  await fs.mkdir(output, { recursive: true });
  await fs.writeFile(path.join(output, 'ocr-local.js'), bundle);
  await fs.writeFile(path.join(output, 'manifest.json'), JSON.stringify(manifest, null, 2) + '\n');
  for (const [name, data] of Object.entries(assets)) {
    if (name.endsWith('.txt')) await fs.writeFile(path.join(output, name), data);
  }
  console.log(`Built offline OCR: ${(Buffer.byteLength(bundle) / 1024 / 1024).toFixed(1)} MiB`);
}
main().catch(error => { console.error(error); process.exitCode = 1; });
